CLs.TXT:
// GT高さ検査 時間取得(シリアル番号)
GT2_A_Inspection_GetTime:=GetTime();
GT2_A_Inspection_GetTime_ST:=DtToString(GT2_A_Inspection_GetTime);
// 秒まで取得するため LEFTは「19」文字指定
// コロンが2つ(14文字目と17文字目)あるので、REPLACEを2回重ねます
// 結果例: '2026-02-02-16:05:30' → '2026-02-02-16-05-30'
GT2_A_Inspection_GetTime_ST_Del:=   REPLACE(REPLACE(LEFT(GT2_A_Inspection_GetTime_ST, UINT#19), STRING#'-', UINT#1, UINT#17), STRING#'-', UINT#1, UINT#14);
// データを格納
Station_A_Data[2].Dates:=GT2_A_Inspection_GetTime_ST_Del;
//GT高さ検査データ取得
Station_A_Data[2].HeightData:=Hgt_A_ComputedValueData;

// 箱詰めX位置：4列×4行、1か所5個積み、合計80個
// Box_Total_CTは既存ラダーで5個ずつ加算済みの値を使用する。
// X開始位置：HMI_RCON2_2_OUT_TargetPos[3] [mm]
// Xピッチ　：HMI_Box_X_Pitch_mm [mm]（符号付き）
// 無効カウントでは目標を更新しない。加算・リセット・移動開始は行わない。

// 1列目：開始位置
IF (Box_Total_CT = INT#5) OR
   (Box_Total_CT = INT#25) OR
   (Box_Total_CT = INT#45) OR
   (Box_Total_CT = INT#65) THEN

    RCON2_2_OUT_TargetPos_mm := HMI_RCON2_2_OUT_TargetPos[3];

// 2列目：開始位置＋1ピッチ
ELSIF (Box_Total_CT = INT#10) OR
      (Box_Total_CT = INT#30) OR
      (Box_Total_CT = INT#50) OR
      (Box_Total_CT = INT#70) THEN

    RCON2_2_OUT_TargetPos_mm :=
        HMI_RCON2_2_OUT_TargetPos[3] +
        HMI_Box_X_Pitch_mm;

// 3列目：開始位置＋2ピッチ
ELSIF (Box_Total_CT = INT#15) OR
      (Box_Total_CT = INT#35) OR
      (Box_Total_CT = INT#55) OR
      (Box_Total_CT = INT#75) THEN

    RCON2_2_OUT_TargetPos_mm :=
        HMI_RCON2_2_OUT_TargetPos[3] +
        HMI_Box_X_Pitch_mm * LREAL#2.0;

// 4列目：開始位置＋3ピッチ
ELSIF (Box_Total_CT = INT#20) OR
      (Box_Total_CT = INT#40) OR
      (Box_Total_CT = INT#60) OR
      (Box_Total_CT = INT#80) THEN

    RCON2_2_OUT_TargetPos_mm :=
        HMI_RCON2_2_OUT_TargetPos[3] +
        HMI_Box_X_Pitch_mm * LREAL#3.0;
END_IF;

// 箱詰めY位置：X方向4か所（20個）ごとに次の行へ進む。
// Y開始位置：HMI_RCON2_3_OUT_TargetPos[3] [mm]
// Yピッチ　：HMI_Box_Y_Pitch_mm [mm]（符号付き）
// 位置選択前に既存ラダーで5個加算。無効カウントでは目標を更新しない。

// 1行目：開始位置
IF (Box_Total_CT = INT#5) OR
   (Box_Total_CT = INT#10) OR
   (Box_Total_CT = INT#15) OR
   (Box_Total_CT = INT#20) THEN

    RCON2_3_OUT_TargetPos_mm := HMI_RCON2_3_OUT_TargetPos[3];

// 2行目：開始位置＋1ピッチ
ELSIF (Box_Total_CT = INT#25) OR
      (Box_Total_CT = INT#30) OR
      (Box_Total_CT = INT#35) OR
      (Box_Total_CT = INT#40) THEN

    RCON2_3_OUT_TargetPos_mm :=
        HMI_RCON2_3_OUT_TargetPos[3] + HMI_Box_Y_Pitch_mm;

// 3行目：開始位置＋2ピッチ
ELSIF (Box_Total_CT = INT#45) OR
      (Box_Total_CT = INT#50) OR
      (Box_Total_CT = INT#55) OR
      (Box_Total_CT = INT#60) THEN

    RCON2_3_OUT_TargetPos_mm :=
        HMI_RCON2_3_OUT_TargetPos[3] + HMI_Box_Y_Pitch_mm * LREAL#2.0;

// 4行目：開始位置＋3ピッチ
ELSIF (Box_Total_CT = INT#65) OR
      (Box_Total_CT = INT#70) OR
      (Box_Total_CT = INT#75) OR
      (Box_Total_CT = INT#80) THEN

    RCON2_3_OUT_TargetPos_mm :=
        HMI_RCON2_3_OUT_TargetPos[3] + HMI_Box_Y_Pitch_mm * LREAL#3.0;
END_IF;

// 【RCON1／Node1／6軸】直接数値指定の通信変換。加速と減速は共通値です。
// 前提：全軸が直接数値指定、直動軸、共通8ワード＋軸番号順に各8ワード。実機の設定は別途照合。
// OUTはPLC→RCONの指令、INはRCON→PLCの現在値・状態。名前はPLCから見た方向です。
// 構造体は人が扱いやすい箱、Eで始まる変数はI/Oマップに割付済みの通信の出入口です。
// このSTは変換と許可付き代入までです。自動運転、通信正常判定、安全停止、開始受付の管理は含みません。
// Sysmacでの全体再ビルドと実機照合は未実施です。このファイルだけで実機へ転送しないでください。
// 【① 入力を読む → 単位を戻す → 構造体INへ入れる】
// 112Byte分の56個のUINTをRxRawへコピーします。ここでは実入力変数へ一切代入しません。
// 共通領域はIN00～07、6軸分はIN08～55。IN56以降は存在しないため読みません。
// RxRawは通信のまま、RxWordは必要なら上下バイトを入れ替えた後の値です。
// 注意：確認前も数値・状態は仮に復元します。DataValid=FALSEの値で機械を動かさないでください。
RCON1_RxRaw[0] := E001_In_IN00_2004_01;
RCON1_RxRaw[1] := E001_In_IN01_2004_02;
RCON1_RxRaw[2] := E001_In_IN02_2004_03;
RCON1_RxRaw[3] := E001_In_IN03_2004_04;
RCON1_RxRaw[4] := E001_In_IN04_2004_05;
RCON1_RxRaw[5] := E001_In_IN05_2004_06;
RCON1_RxRaw[6] := E001_In_IN06_2004_07;
RCON1_RxRaw[7] := E001_In_IN07_2004_08;
RCON1_RxRaw[8] := E001_In_IN08_2004_09;
RCON1_RxRaw[9] := E001_In_IN09_2004_0A;
RCON1_RxRaw[10] := E001_In_IN10_2004_0B;
RCON1_RxRaw[11] := E001_In_IN11_2004_0C;
RCON1_RxRaw[12] := E001_In_IN12_2004_0D;
RCON1_RxRaw[13] := E001_In_IN13_2004_0E;
RCON1_RxRaw[14] := E001_In_IN14_2004_0F;
RCON1_RxRaw[15] := E001_In_IN15_2004_10;
RCON1_RxRaw[16] := E001_In_IN16_2004_11;
RCON1_RxRaw[17] := E001_In_IN17_2004_12;
RCON1_RxRaw[18] := E001_In_IN18_2004_13;
RCON1_RxRaw[19] := E001_In_IN19_2004_14;
RCON1_RxRaw[20] := E001_In_IN20_2004_15;
RCON1_RxRaw[21] := E001_In_IN21_2004_16;
RCON1_RxRaw[22] := E001_In_IN22_2004_17;
RCON1_RxRaw[23] := E001_In_IN23_2004_18;
RCON1_RxRaw[24] := E001_In_IN24_2004_19;
RCON1_RxRaw[25] := E001_In_IN25_2004_1A;
RCON1_RxRaw[26] := E001_In_IN26_2004_1B;
RCON1_RxRaw[27] := E001_In_IN27_2004_1C;
RCON1_RxRaw[28] := E001_In_IN28_2004_1D;
RCON1_RxRaw[29] := E001_In_IN29_2004_1E;
RCON1_RxRaw[30] := E001_In_IN30_2004_1F;
RCON1_RxRaw[31] := E001_In_IN31_2004_20;
RCON1_RxRaw[32] := E001_In_IN32_2004_21;
RCON1_RxRaw[33] := E001_In_IN33_2004_22;
RCON1_RxRaw[34] := E001_In_IN34_2004_23;
RCON1_RxRaw[35] := E001_In_IN35_2004_24;
RCON1_RxRaw[36] := E001_In_IN36_2004_25;
RCON1_RxRaw[37] := E001_In_IN37_2004_26;
RCON1_RxRaw[38] := E001_In_IN38_2004_27;
RCON1_RxRaw[39] := E001_In_IN39_2004_28;
RCON1_RxRaw[40] := E001_In_IN40_2004_29;
RCON1_RxRaw[41] := E001_In_IN41_2004_2A;
RCON1_RxRaw[42] := E001_In_IN42_2004_2B;
RCON1_RxRaw[43] := E001_In_IN43_2004_2C;
RCON1_RxRaw[44] := E001_In_IN44_2004_2D;
RCON1_RxRaw[45] := E001_In_IN45_2004_2E;
RCON1_RxRaw[46] := E001_In_IN46_2004_2F;
RCON1_RxRaw[47] := E001_In_IN47_2004_30;
RCON1_RxRaw[48] := E001_In_IN48_2004_31;
RCON1_RxRaw[49] := E001_In_IN49_2004_32;
RCON1_RxRaw[50] := E001_In_IN50_2004_33;
RCON1_RxRaw[51] := E001_In_IN51_2004_34;
RCON1_RxRaw[52] := E001_In_IN52_2004_35;
RCON1_RxRaw[53] := E001_In_IN53_2004_36;
RCON1_RxRaw[54] := E001_In_IN54_2004_37;
RCON1_RxRaw[55] := E001_In_IN55_2004_38;
// 取説の論理ワードへ正規化。Swapは1ワード内の上下バイト交換です。
// SwapBytesは推測で設定せず、既知の位置とbitで実機照合してください。
FOR ConvWordIndex := INT#0 TO INT#55 DO
    RCON1_RxWord[ConvWordIndex] := UINT_TO_WORD(RCON1_RxRaw[ConvWordIndex]);
    IF RCON1_SwapBytes THEN
        RCON1_RxWord[ConvWordIndex] := Swap(RCON1_RxWord[ConvWordIndex]);
    END_IF;
END_FOR;

ConvUnitOK := (RCON1_SpeedUnit_mm_s = LREAL#1.0) OR
              (RCON1_SpeedUnit_mm_s = LREAL#0.1);

// 【①-2 共通状態】IN00はユニット全体、IN01は各軸のリンク情報です。
// TestABit(ワード, bit番号)は、そのスイッチがONかをBOOLで取り出す命令です。
// 例：IN01のb0は軸No.0→配列[1]、b1は軸No.1→配列[2]。配列番号と実機軸番号は1違います。
// 共通固定領域。ここで使うbit番号は取説の論理bitです（MJ0384 6-24～6-25）。
RCON1_GwRun := TestABit(RCON1_RxWord[0], USINT#15);
RCON1_GwControllerCommLatch := TestABit(RCON1_RxWord[0], USINT#14);
RCON1_GwAxisCommError := TestABit(RCON1_RxWord[0], USINT#13);
RCON1_GwManual := TestABit(RCON1_RxWord[0], USINT#12);
RCON1_GwHeavyAlarm := TestABit(RCON1_RxWord[0], USINT#11);
RCON1_GwLightAlarm := TestABit(RCON1_RxWord[0], USINT#10);
RCON1_GwSystemStop := TestABit(RCON1_RxWord[0], USINT#8);
RCON1_GwAlarmCode := WORD_TO_UINT(RCON1_RxWord[0] AND WORD#16#00FF);
FOR ConvWordIndex := INT#0 TO INT#4 DO
    RCON1_PowerStateRaw[ConvWordIndex] := RCON1_RxWord[ConvWordIndex + INT#2];
END_FOR;

// 【①-3 軸ごとに同じ読取りを繰り返す】
// FORは1～6軸を順番に処理します。ConvBaseはその軸の先頭番号です。
// 計算：8+(軸番号-1)×8。1軸目=8、2軸目=16、3軸目=24。先頭8ワードは共通領域です。
FOR ConvAxisIndex := INT#1 TO INT#6 DO
    ConvBase := INT#8 + (ConvAxisIndex - INT#1) * INT#8;
    RCON1_AxisLinked[ConvAxisIndex] :=
        TestABit(RCON1_RxWord[1], INT_TO_USINT(ConvAxisIndex - INT#1));

// 例：下位2540／上位0なら32bit値2540→25.40mm。
// 上位を16bit左に動かして下位とORで重ねます。SHLが左シフト、ORがビットの合成です。
// 負位置はDWORD_TO_DINTで符号を復元。下位62996／上位65535なら-2540→-25.40mm。
    // 現在位置：下位・上位を結合、符号付き32bitとして解釈、0.01mmをmmへ。
    ConvDWord := SHL(WORD_TO_DWORD(RCON1_RxWord[ConvBase + INT#1]), ULINT#16)
                 OR WORD_TO_DWORD(RCON1_RxWord[ConvBase]);
    RCON1_IN[ConvAxisIndex].ActualPos_mm :=
        DINT_TO_LREAL(DWORD_TO_DINT(ConvDWord)) * LREAL#0.01;

    // 電流：32bitのmA。RCON-PCでは指令電流であり、実測トルクではありません。
    ConvDWord := SHL(WORD_TO_DWORD(RCON1_RxWord[ConvBase + INT#3]), ULINT#16)
                 OR WORD_TO_DWORD(RCON1_RxWord[ConvBase + INT#2]);
    RCON1_IN[ConvAxisIndex].Current_mA := DWORD_TO_DINT(ConvDWord);

    // 現在速度：16bitの負数をINTとして読む。UINTのまま速度にしません。
    IF ConvUnitOK THEN
        RCON1_IN[ConvAxisIndex].ActualSpeed_mm_s :=
            INT_TO_LREAL(WORD_TO_INT(RCON1_RxWord[ConvBase + INT#4])) * RCON1_SpeedUnit_mm_s;
    END_IF;
    // 単位不明のとき速度は前値を保持し、DataValidはFALSEにします。
    // 軸内の+5ワードは予約のため値を使用しません。
    RCON1_IN[ConvAxisIndex].AlarmCode := WORD_TO_UINT(RCON1_RxWord[ConvBase + INT#6]);

// 例：Status.ServoReady=TRUEは「サーボON状態を受信した」という意味。
// OUT側Control.ServoOn=TRUEは「サーボONを要求する」という意味で、指令と結果を区別します。
    // 状態ワード：12個のBOOLへ分解。予約b6,b9～11は使いません。
    RCON1_IN[ConvAxisIndex].Status.PositionDone := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#0);
    RCON1_IN[ConvAxisIndex].Status.HomeDone := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#1);
    RCON1_IN[ConvAxisIndex].Status.Moving := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#2);
    RCON1_IN[ConvAxisIndex].Status.Alarm := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#3);
    RCON1_IN[ConvAxisIndex].Status.ServoReady := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#4);
    RCON1_IN[ConvAxisIndex].Status.PushMiss := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#5);
    RCON1_IN[ConvAxisIndex].Status.OverloadWarning := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#7);
    RCON1_IN[ConvAxisIndex].Status.CommandDone := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#8);
    RCON1_IN[ConvAxisIndex].Status.Zone1 := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#12);
    RCON1_IN[ConvAxisIndex].Status.Zone2 := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#13);
    RCON1_IN[ConvAxisIndex].Status.ControllerReady := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#14);
    RCON1_IN[ConvAxisIndex].Status.EmergencyStop := TestABit(RCON1_RxWord[ConvBase + INT#7], USINT#15);

    // DataValidは直接受信bitではなく、今回の内部設計で決めた内部判定です。
    // CommOKはCPUの実通信状態から別途作成。単にTRUE固定にしないでください。
    // DataValidは運転許可や安全保証ではありません。各異常・原点等は別途確認。
    RCON1_IN[ConvAxisIndex].DataValid := RCON1_CommOK AND RCON1_LayoutConfirmed
        AND RCON1_ByteOrderConfirmed AND ConvUnitOK AND RCON1_GwRun
        AND RCON1_AxisLinked[ConvAxisIndex] AND NOT RCON1_GwAxisCommError;
END_FOR;

// 【RCON1／Node1／6軸】直接数値指定の通信変換。加速と減速は共通値です。
// 前提：全軸が直接数値指定、直動軸、共通8ワード＋軸番号順に各8ワード。実機の設定は別途照合。
// OUTはPLC→RCONの指令、INはRCON→PLCの現在値・状態。名前はPLCから見た方向です。
// 構造体は人が扱いやすい箱、Eで始まる変数はI/Oマップに割付済みの通信の出入口です。
// このSTは変換と許可付き代入までです。自動運転、通信正常判定、安全停止、開始受付の管理は含みません。
// Sysmacでの全体再ビルドと実機照合は未実施です。このファイルだけで実機へ転送しないでください。
// 【② OUTの入力値を通信データへ翻訳する。まだ実出力には書かない】
// 例：RCON1_OUT[1].TargetPos_mm に25.40を設定すると、1軸目の25.40mm指令候補を作ります。
// 位置はmm、速度はmm/s、加減速はG、押付け制限は%。人が扱う単位のまま構造体へ設定します。
// TxWordは取説のbit並び、TxUIntは実通信へ渡す候補。③の許可がなければ機械には書込みません。
// EncodeError=0は数値変換可能という意味だけです。実際のストローク・速度上限・干渉は別に検査します。
// エラー番号：1速度単位、2位置、3位置決め幅、4速度、5加減速、6押付け、7ジョグ両方向。
// 速度0や幅0を正常運転値と認めたものではありません。実機に適した条件はMotionPermitの作成側で確認。
// 丸め：位置等は四捨五入、押付け制限のみ小数部を切捨てます。

ConvUnitOK := (RCON1_SpeedUnit_mm_s = LREAL#1.0) OR
              (RCON1_SpeedUnit_mm_s = LREAL#0.1);

// 共通制御：MONは論理b15、RTEは論理b13。他のbitは0。
// MONを落とす処理を安全停止として扱わないでください。
RCON1_TxWord[0] := WORD#16#0000;
IF RCON1_GwMON_Request THEN
    RCON1_TxWord[0] := RCON1_TxWord[0] OR WORD#16#8000;
END_IF;
IF RCON1_GwRTE_Request THEN
    RCON1_TxWord[0] := RCON1_TxWord[0] OR WORD#16#2000;
END_IF;

FOR ConvAxisIndex := INT#1 TO INT#6 DO
    ConvBase := INT#8 + (ConvAxisIndex - INT#1) * INT#8;
    RCON1_EncodeError[ConvAxisIndex] := UINT#0;

    // 比較で範囲を確認してから型変換するため、NaN・無限大も変換対象から外れます。
    // 位置・幅9999.99mmはこの案で採用する通信範囲の上限で、実機ストロークではありません。
    IF NOT ConvUnitOK THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#1;
    ELSIF NOT ((RCON1_OUT[ConvAxisIndex].TargetPos_mm >= LREAL#-9999.99) AND
               (RCON1_OUT[ConvAxisIndex].TargetPos_mm <= LREAL#9999.99)) THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#2;
    ELSIF NOT ((RCON1_OUT[ConvAxisIndex].PositionBand_mm >= LREAL#0.0) AND
               (RCON1_OUT[ConvAxisIndex].PositionBand_mm <= LREAL#9999.99)) THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#3;
    ELSIF NOT ((RCON1_OUT[ConvAxisIndex].Speed_mm_s >= LREAL#0.0) AND
               (RCON1_OUT[ConvAxisIndex].Speed_mm_s <= LREAL#65535.0 * RCON1_SpeedUnit_mm_s)) THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#4;
    ELSIF NOT ((RCON1_OUT[ConvAxisIndex].AccDec_G >= LREAL#0.0) AND
               (RCON1_OUT[ConvAxisIndex].AccDec_G <= LREAL#655.35)) THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#5;
    ELSIF NOT ((RCON1_OUT[ConvAxisIndex].PushLimit_pct >= LREAL#0.0) AND
               (RCON1_OUT[ConvAxisIndex].PushLimit_pct <= LREAL#200.0)) THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#6;
    ELSIF RCON1_OUT[ConvAxisIndex].Control.JogMinus AND RCON1_OUT[ConvAxisIndex].Control.JogPlus THEN
        RCON1_EncodeError[ConvAxisIndex] := UINT#7;
    END_IF;

    RCON1_EncodeOK[ConvAxisIndex] := RCON1_EncodeError[ConvAxisIndex] = UINT#0;
    IF RCON1_EncodeOK[ConvAxisIndex] THEN
    // 【数値例】TargetPos_mm=25.40→×100で2540。下位ワード2540、上位ワード0。
// 700.25mm→70025なので下位4489、上位1。65536を超えた分が上位に入ります。
// DINTは符号付きの数、DWORDは同じ32bitの模様。負数の符号を壊さず分割するために使い分けます。
// TRUNCは小数部を捨てます。正数+0.5／負数-0.5を先に行い、四捨五入を明示しています。
    // 目標位置：mmから0.01mmの符号付き整数へ。
        ConvScaled := RCON1_OUT[ConvAxisIndex].TargetPos_mm * LREAL#100.0;
        IF ConvScaled >= LREAL#0.0 THEN
            ConvPos := LINT_TO_DINT(TRUNC(ConvScaled + LREAL#0.5));
        ELSE
            ConvPos := LINT_TO_DINT(TRUNC(ConvScaled - LREAL#0.5));
        END_IF;
        // 負数を含む32bitパターンを保ち、下位・上位の16bitへ分割。
        ConvDWord := DINT_TO_DWORD(ConvPos);
        RCON1_TxWord[ConvBase] := DWORD_TO_WORD(ConvDWord AND DWORD#16#0000FFFF);
        RCON1_TxWord[ConvBase + INT#1] := DWORD_TO_WORD(SHR(ConvDWord, ULINT#16));

        // 位置決め幅：非負の内部整数としてUDINTを選定（メーカーの符号なし保証ではありません）。
        ConvBand := LINT_TO_UDINT(TRUNC(RCON1_OUT[ConvAxisIndex].PositionBand_mm * LREAL#100.0 + LREAL#0.5));
        ConvDWord := UDINT_TO_DWORD(ConvBand);
        RCON1_TxWord[ConvBase + INT#2] := DWORD_TO_WORD(ConvDWord AND DWORD#16#0000FFFF);
        RCON1_TxWord[ConvBase + INT#3] := DWORD_TO_WORD(SHR(ConvDWord, ULINT#16));

// 速度20mm/s：速度単位1.0なら20、0.1なら200を送信します。
// 加減速0.20G：×100して20。加速と減速の両方に同じ値を使います。
// 押付け50%：×255÷100=127.5を切捨てて127。押付けの使用可否・上限は実機仕様で別確認。
        // 速度は1カウント量が1.0か0.1かで値が10倍変わります。
        ConvSpeed := LINT_TO_UINT(TRUNC(RCON1_OUT[ConvAxisIndex].Speed_mm_s / RCON1_SpeedUnit_mm_s + LREAL#0.5));
        ConvAccDec := LINT_TO_UINT(TRUNC(RCON1_OUT[ConvAxisIndex].AccDec_G * LREAL#100.0 + LREAL#0.5));
        ConvPush := LINT_TO_UINT(TRUNC(RCON1_OUT[ConvAxisIndex].PushLimit_pct * LREAL#255.0 / LREAL#100.0));
        RCON1_TxWord[ConvBase + INT#4] := UINT_TO_WORD(ConvSpeed);
        RCON1_TxWord[ConvBase + INT#5] := UINT_TO_WORD(ConvAccDec);
        RCON1_TxWord[ConvBase + INT#6] := UINT_TO_WORD(ConvPush);
    END_IF;
    // 不正値の場合、数値ワードは前値保持。EncodeOK=FALSEで03の書込みを抑止。
    // 前値保持は停止指令ではありません。停止・異常処理は別途設計してください。

    // Controlを論理bitへ詰める。予約b9は必ず0。
    RCON1_TxWord[ConvBase + INT#7] := WORD#16#0000;
// b0 DSTR／Control.Start：TRUEで開始要求。受付応答と10ms以上の保持を確認してOFF。常時ONにしない。
    IF RCON1_OUT[ConvAxisIndex].Control.Start THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0001;
    END_IF;
// b1 HOME／Control.Home：TRUEで原点復帰を指令。原点復帰完了はIN側HomeDoneで確認。
    IF RCON1_OUT[ConvAxisIndex].Control.Home THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0002;
    END_IF;
// b2 STP／Control.Pause：TRUEで一時停止、FALSEで解除。非常停止・安全停止の代用ではない。
    IF RCON1_OUT[ConvAxisIndex].Control.Pause THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0004;
    END_IF;
// b3 RES／Control.Reset：TRUEでアラームリセット要求。コールドスタート級の異常には使用できない。
    IF RCON1_OUT[ConvAxisIndex].Control.Reset THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0008;
    END_IF;
// b4 SON／Control.ServoOn：TRUEでサーボON要求。ON状態はIN側ServoReadyで確認。
    IF RCON1_OUT[ConvAxisIndex].Control.ServoOn THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0010;
    END_IF;
// b5 JISL／Control.InchingSelect：TRUEは一定距離のインチング、FALSEは押している間のジョグ。
    IF RCON1_OUT[ConvAxisIndex].Control.InchingSelect THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0020;
    END_IF;
// b6 JVEL／Control.JogSpeedSelect：FALSEは速度No.26・距離No.48、TRUEは速度No.47または指令速度・距離No.49。
    IF RCON1_OUT[ConvAxisIndex].Control.JogSpeedSelect THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0040;
    END_IF;
// b7 JOG-／Control.JogMinus：TRUEで原点方向へジョグ。反対方向指令との同時ONを防ぐ。
    IF RCON1_OUT[ConvAxisIndex].Control.JogMinus THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0080;
    END_IF;
// b8 JOG+／Control.JogPlus：TRUEで反原点方向へジョグ。反対方向指令との同時ONを防ぐ。
    IF RCON1_OUT[ConvAxisIndex].Control.JogPlus THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0100;
    END_IF;
// b10 GSL0／Control.GainSelect0：GainSelect1と組合せてサーボゲインセット0～3を選ぶ。機械調整用。
    IF RCON1_OUT[ConvAxisIndex].Control.GainSelect0 THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0400;
    END_IF;
// b11 GSL1／Control.GainSelect1：GainSelect0との2bitで選択。速度指令とは別の機能。
    IF RCON1_OUT[ConvAxisIndex].Control.GainSelect1 THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#0800;
    END_IF;
// b12 PUSH／Control.PushEnable：TRUEは押付け、FALSEは通常位置決め。押付け条件は別途確認。
    IF RCON1_OUT[ConvAxisIndex].Control.PushEnable THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#1000;
    END_IF;
// b13 DIR／Control.PushDirection：CON方式押付け時、TRUEは反原点方向、FALSEは原点方向。
    IF RCON1_OUT[ConvAxisIndex].Control.PushDirection THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#2000;
    END_IF;
// b14 INC／Control.RelativeMove：FALSEは絶対座標、TRUEは現在位置からの相対移動量。
    IF RCON1_OUT[ConvAxisIndex].Control.RelativeMove THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#4000;
    END_IF;
// b15 BKRL／Control.BrakeRelease：TRUEはブレーキ強制解除。通常FALSE。縦軸では落下等の危険がある。
    IF RCON1_OUT[ConvAxisIndex].Control.BrakeRelease THEN
        RCON1_TxWord[ConvBase + INT#7] := RCON1_TxWord[ConvBase + INT#7] OR WORD#16#8000;
    END_IF;
